import React, { useEffect } from 'react';
import { useForm } from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import { Form, FormControl, FormField, FormItem, FormLabel, FormMessage } from "./ui/form";
import { Input } from "./ui/input";
import { customerInfoSchema, CustomerInfoFormData } from "../lib/validations";
import { CustomerInfoProps } from '../types';

const CustomerInfo: React.FC<CustomerInfoProps> = ({ onChange }) => {
    const form = useForm<CustomerInfoFormData>({
        resolver: zodResolver(customerInfoSchema),
        defaultValues: {
            firstName: "",
            stock: "",
            salesperson: "",
            address1: "",
            city: "",
            state: "",
            zipcode: "",
            number: "",
            email: "",
        },
    });

    // Watch form values and update parent state
    const watchedValues = form.watch();

    useEffect(() => {
        if (onChange) {
            onChange((previousState) => ({
                ...previousState,
                customerInfo: watchedValues,
            }));
        }
    }, [watchedValues, onChange]);

    return (
        <div className="po-book-form">
            <Form {...form}>
                <form className="space-y-6">
                    <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                        <FormField
                            control={form.control}
                            name="firstName"
                            render={({ field }) => (
                                <FormItem>
                                    <FormLabel className="text-white">Customer Name</FormLabel>
                                    <FormControl>
                                        <Input
                                            placeholder="Customer Name"
                                            className="bg-black text-white border-corvette-gray focus:border-blue-500"
                                            {...field}
                                        />
                                    </FormControl>
                                    <FormMessage />
                                </FormItem>
                            )}
                        />

                        <FormField
                            control={form.control}
                            name="stock"
                            render={({ field }) => (
                                <FormItem>
                                    <FormLabel className="text-white">Stock#</FormLabel>
                                    <FormControl>
                                        <Input
                                            placeholder="Stock"
                                            className="bg-black text-white border-corvette-gray focus:border-blue-500"
                                            {...field}
                                        />
                                    </FormControl>
                                    <FormMessage />
                                </FormItem>
                            )}
                        />

                        <FormField
                            control={form.control}
                            name="salesperson"
                            render={({ field }) => (
                                <FormItem>
                                    <FormLabel className="text-white">Salesperson</FormLabel>
                                    <FormControl>
                                        <Input
                                            placeholder="Salesperson"
                                            className="bg-black text-white border-corvette-gray focus:border-blue-500"
                                            {...field}
                                        />
                                    </FormControl>
                                    <FormMessage />
                                </FormItem>
                            )}
                        />
                    </div>

                    <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
                        <FormField
                            control={form.control}
                            name="address1"
                            render={({ field }) => (
                                <FormItem>
                                    <FormLabel className="text-white">Address</FormLabel>
                                    <FormControl>
                                        <Input
                                            placeholder="1234 Main St"
                                            className="bg-black text-white border-corvette-gray focus:border-blue-500"
                                            {...field}
                                        />
                                    </FormControl>
                                    <FormMessage />
                                </FormItem>
                            )}
                        />

                        <FormField
                            control={form.control}
                            name="city"
                            render={({ field }) => (
                                <FormItem>
                                    <FormLabel className="text-white">City</FormLabel>
                                    <FormControl>
                                        <Input
                                            placeholder="City"
                                            className="bg-black text-white border-corvette-gray focus:border-blue-500"
                                            {...field}
                                        />
                                    </FormControl>
                                    <FormMessage />
                                </FormItem>
                            )}
                        />

                        <FormField
                            control={form.control}
                            name="state"
                            render={({ field }) => (
                                <FormItem>
                                    <FormLabel className="text-white">State</FormLabel>
                                    <FormControl>
                                        <Input
                                            placeholder="State"
                                            className="bg-black text-white border-corvette-gray focus:border-blue-500"
                                            {...field}
                                        />
                                    </FormControl>
                                    <FormMessage />
                                </FormItem>
                            )}
                        />

                        <FormField
                            control={form.control}
                            name="zipcode"
                            render={({ field }) => (
                                <FormItem>
                                    <FormLabel className="text-white">Zip</FormLabel>
                                    <FormControl>
                                        <Input
                                            placeholder="Zip code"
                                            className="bg-black text-white border-corvette-gray focus:border-blue-500"
                                            {...field}
                                        />
                                    </FormControl>
                                    <FormMessage />
                                </FormItem>
                            )}
                        />
                    </div>

                    <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                        <FormField
                            control={form.control}
                            name="number"
                            render={({ field }) => (
                                <FormItem>
                                    <FormLabel className="text-white">Mobile Phone</FormLabel>
                                    <FormControl>
                                        <Input
                                            type="tel"
                                            placeholder="Mobile Phone"
                                            className="bg-black text-white border-corvette-gray focus:border-blue-500"
                                            {...field}
                                        />
                                    </FormControl>
                                    <FormMessage />
                                </FormItem>
                            )}
                        />

                        <FormField
                            control={form.control}
                            name="email"
                            render={({ field }) => (
                                <FormItem>
                                    <FormLabel className="text-white">Email</FormLabel>
                                    <FormControl>
                                        <Input
                                            type="email"
                                            placeholder="Enter email"
                                            className="bg-black text-white border-corvette-gray focus:border-blue-500"
                                            {...field}
                                        />
                                    </FormControl>
                                    <FormMessage />
                                </FormItem>
                            )}
                        />
                    </div>

                </form>
            </Form>
        </div>
    );
};

export default CustomerInfo;